const CACHE='shuihu-native-v98';
const SHELL=['./','./index.html','./style.css','./theme.css','./fonts-wenkai.css','./js/app.js','./js/art-style.js','./js/foreground.js','./data/foreground.json','./data/art-styles.json','./data/item-descriptions.json','./data/worldmap.json','./data/music.json','./data/objectives.json','./data/props.json','./data/heroes108.json','./data/characters-hd.json','./js/joystick.js','./data/unicode.json','./js/pathfinding.js','./js/story.js','./js/title-intro.js','./js/battle.js','./js/battle-ai.js','./js/battle-session.js','./js/battle-setup.js','./js/stage-scheduler.js','./js/stage-rules.js','./data/battle-stages.json','./data/assets.json','./data/story.json','./data/battle.json','./data/initial-world.json','./data/npc-dialogues.json'];
// cache:'reload' so a new version never copies stale files out of the browser's HTTP cache.
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(SHELL.map(url=>new Request(url,{cache:'reload'}))))));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('shuihu-native-')&&key!==CACHE).map(key=>caches.delete(key))))));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==location.origin||event.request.headers.has('range'))return;event.respondWith(fetch(event.request,{cache:'no-cache'}).then(response=>{if(response.ok&&!response.redirected&&response.type==='basic'){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy));}return response;}).catch(()=>caches.match(event.request)));});
